cypress_script:
describe('Alert and Confirm Dialogs', () => {
  it('should show alert dialog when alert button is clicked', () => {
    cy.visit('https://demoqa.com/alerts');
    cy.get('#alertButton').click();
    cy.on('window:alert', (text) => {
      expect(text).to.exist;
    });
  });
  it('should not change URL when confirm button is clicked', () => {
    cy.visit('https://demoqa.com/alerts');
    cy.get('#confirmButton').click();
    cy.url().should('eq', 'https://demoqa.com/alerts');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';
test.describe('Alert and Confirm Dialogs', () => {
  test('should show alert dialog when alert button is clicked', async ({ page }) => {
    await page.goto('https://demoqa.com/alerts');
    await page.click('#alertButton');
    page.on('dialog', dialog => {
      expect(dialog).toBeDefined();
      dialog.dismiss();
    });
  });
  test('should not change URL when confirm button is clicked', async ({ page }) => {
    await page.goto('https://demoqa.com/alerts');
    await page.click('#confirmButton');
    await expect(page).toHaveURL('https://demoqa.com/alerts');
  });
});
